const $ = s => document.querySelector(s);
if ('scrollRestoration' in history) history.scrollRestoration='auto';
const icons={terminal:'<path d="m5 7 5 5-5 5m8 0h6"/><rect x="2" y="3" width="20" height="18" rx="3"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.1M7 17.5h.1M12 6.5h5M12 17.5h5"/>',network:'<rect x="9" y="2" width="6" height="6" rx="1"/><rect x="2" y="16" width="6" height="6" rx="1"/><rect x="16" y="16" width="6" height="6" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',cube:'<path d="m12 2 9 5v10l-9 5-9-5V7Zm0 10 9-5M12 12 3 7m9 5v10M7.5 4.5l9 5v5"/>',pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4M18 9h4m-4 6h4"/>',layers:'<path d="m12 2 10 5-10 5L2 7Zm-10 10 10 5 10-5M2 17l10 5 10-5"/>',flask:'<path d="M9 2h6M10 2v7L4 19a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3L14 9V2M7 15h10"/>',book:'<path d="M12 5c-3-2-6-2-10-1v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v16"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function writeStore(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}
let progress=readStore('cloudinfra-progress',{}); if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};
let checks=readStore('cloudinfra-checks',{}); if(!checks||typeof checks!=='object'||Array.isArray(checks))checks={};
let filter='all',observer,searchIndex=-1,searchItems=[],toastTimer;
const ordered=modules.flatMap(m=>articles.filter(a=>a.module===m.id));
const moduleFor=id=>modules.find(m=>m.id===id);
const countRead=()=>ordered.filter(a=>progress[a.id]).length;
const tags=items=>`<div class="tag-row">${items.map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join('')}</div>`;
const articleURL=id=>`/article/${id}/`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
const footer=()=>`<footer class="footer"><div class="container"><span>© 2026 InfraGuide · 从理解原理，到构建系统。</span><span>原创工程内容 · <a href="#/about">关于本站</a> · <a href="#/roadmap">学习路线</a></span></div></footer>`;
function moduleCard(m){const n=articles.filter(a=>a.module===m.id).length;return `<a href="#/module/${m.id}" class="module-card ${m.featured?'featured':''}"><div class="card-top"><span class="module-icon">${icon(m.icon)}</span>${m.featured?'<span class="small-badge">AI 训练主线</span>':`<span class="card-number">${m.n}</span>`}</div><h3>${m.name}</h3><p>${m.desc}</p>${tags(m.tags)}<div class="card-footer"><span>${n} 篇内容</span><b>开始阅读 ↗</b></div></a>`}
function renderModuleGrid(){const list=filter==='all'?modules:modules.filter(m=>m.track===filter);$('#module-grid').innerHTML=list.map(moduleCard).join('');normalizeInternalLinks();document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)})}
function home(){homePage()}
function sidebar(moduleId,current){return sidebarView(moduleId,current)}
function breadcrumbs(m,end=''){return `<div class="breadcrumb"><a href="#/">知识库</a><span>／</span><a href="#/module/${m.id}">${m.name}</a>${end?`<span>／</span><span>${end}</span>`:''}</div>`}
function modulePage(m){document.title=`${m.name} · InfraGuide`;const list=articles.filter(a=>a.module===m.id);$('#app').innerHTML=`<main class="doc-layout" id="main" tabindex="-1">${sidebar(m.id)}<article class="article">${breadcrumbs(m)}<div class="eyebrow">MODULE ${m.n} / ${m.en}</div><h1 style="margin-top:18px">${m.name}</h1><p class="description">${m.desc}</p>${tags(m.tags)}${m.id==="training"?"":moduleOverview(m,list)}${m.id==="training"?courseIntro()+sectionGroup(list):list.map(chapterLink).join("")}<div class="callout"><strong>学习建议</strong><p>把概念与实际系统对应起来：画出数据路径，写下观测指标，再设计一次小规模实验。</p></div><a class="btn secondary" href="#/roadmap">查看完整学习路线 →</a></article><aside class="toc"><div class="toc-title">本模块</div>${list.map(a=>`<a href="${articleURL(a.id)}">${a.number} ${a.title}</a>`).join('')}<div class="toc-note">先理解原理，再验证假设。</div></aside></main>${footer()}`}
function articlePage(a,anchor){const m=moduleFor(a.module),sequence=ordered.filter(x=>moduleFor(x.module).track===m.track),idx=sequence.indexOf(a),prev=sequence[idx-1],next=sequence[idx+1];document.title=`${a.title} · InfraGuide`;$('#app').innerHTML=`<main class="doc-layout" id="main" tabindex="-1">${sidebar(a.module,a.id)}<article class="article">${breadcrumbs(m,a.number)}<div class="article-meta"><span class="category">${m.name}</span><span>${a.level}</span><span>·</span><span>${a.edition||"训练专题"} · ${a.updated||"2026.11.03"}</span></div><h1>${a.number} ${a.title}</h1><p class="description">${a.desc}</p>${tags(a.tags)}${guidedIntro(a)}${learningContract(a)}${mobileContents(a)}${a.intro!==a.desc?'<p class="intro">'+a.intro+"</p>":""}${a.sections.map((s,i)=>`<section class="article-section" id="section-${i+1}"><h2><span class="section-index">${String(i+1).padStart(2,'0')}</span>${s[0]}</h2>${s[1]}</section>`).join('')}${guidedReview(a)}${a.exercise?'<section class="article-section applied-exercise"><h2><span class="section-index">?</span>迁移练习</h2><p>'+a.exercise[0]+'</p><details class="full-code"><summary>展开参考答案与推理</summary><p>'+a.exercise[1]+'</p></details></section>':''}<section class="article-section" id="self-check"><h2><span class="section-index">✓</span>自我检验</h2><div class="checklist">${a.check.map((c,i)=>`<label><input type="checkbox" data-check="${a.id}:${i}" ${checks[`${a.id}:${i}`]?'checked':''}>${c}</label>`).join('')}<small>勾选代表自我评估，进度仅保存在当前浏览器。</small></div></section><section class="article-section references" id="references"><h2><span class="section-index">↗</span>参考资料</h2>${a.refs.map(r=>`<a href="${sources[r][1]}" target="_blank" rel="noopener noreferrer">${sources[r][0]} ↗</a>`).join('')}</section>${readerActionsHTML(a)}${relatedReading(a)}<div class="completion"><span>把理解变成能力：画出来、讲清楚、做一次实验。</span><button class="read-btn ${progress[a.id]?'done':''}" data-read="${a.id}">${progress[a.id]?'✓ 已读 · 点击取消':'标记为已读'}</button></div><nav class="article-nav" aria-label="相邻文章">${prev?`<a href="${articleURL(prev.id)}"><small>← 上一篇</small>${prev.title}</a>`:'<a href="#/roadmap"><small>← 开始之前</small>完整学习路线</a>'}${next?`<a href="${articleURL(next.id)}"><small>下一篇 →</small>${next.title}</a>`:'<a href="#/"><small>完成本轮阅读 →</small>返回知识库</a>'}</nav></article><aside class="toc"><div class="toc-title">本文目录 / ON THIS PAGE</div>${a.sections.map((s,i)=>`<a data-toc="section-${i+1}" href="${articleURL(a.id)}?section=${i+1}">${i+1}. ${s[0]}</a>`).join('')}<a data-toc="self-check" href="${articleURL(a.id)}?section=self-check">自我检验</a><a data-toc="references" href="${articleURL(a.id)}?section=references">参考资料</a><div class="toc-note">${icon('book')} 阅读 · 理解 · 实践</div></aside></main>${footer()}`;initInteractive();observeSections();if(anchor)requestAnimationFrame(()=>document.getElementById(/^\d+$/.test(anchor)?`section-${anchor}`:anchor)?.scrollIntoView())}
function observeSections(){observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){document.querySelectorAll('[data-toc]').forEach(a=>a.classList.toggle('active',a.dataset.toc===e.target.id));break}}},{rootMargin:'-90px 0px -60% 0px',threshold:0});document.querySelectorAll('.article-section').forEach(s=>observer.observe(s))}
function roadmap(){roadmapPage()}
let currentPath='';
function route(){const hash=location.pathname+(location.search||''),[path,query]=hash.split('?'),parts=path.split('/').filter(Boolean),anchor=new URLSearchParams(query||'').get('section');if(path===currentPath&&parts[0]==='article'&&anchor){document.getElementById(/^\d+$/.test(anchor)?`section-${anchor}`:anchor)?.scrollIntoView();return}currentPath=path;observer?.disconnect();$('#search-dialog').close();$('.top-nav').classList.remove('mobile-open');$('#mobile-menu').setAttribute('aria-expanded','false');document.querySelectorAll('.top-nav a').forEach(a=>a.classList.remove('active'));window.scrollTo({top:0,left:0,behavior:'instant'});if(!parts.length)home();else if(parts[0]==='module'&&moduleFor(parts[1])){modulePage(moduleFor(parts[1]));document.querySelector(`.top-nav a[href="#/module/${parts[1]}"]`)?.classList.add('active')}else if(parts[0]==='article'&&articles.find(a=>a.id===parts[1])){const a=articles.find(a=>a.id===parts[1]);articlePage(a,anchor);document.querySelector(`.top-nav a[href="#/module/${a.module}"]`)?.classList.add('active')}else if(parts[0]==='start')startPage();else if(parts[0]==='outline')outlinePage();else if(parts[0]==='interview'&&parts.length===2&&Object.hasOwn(interviewUnits,parts[1]))workshopPage(parts[1]);else if(parts[0]==='interview'&&parts.length===1)interviewPage();else if(parts[0]==='roadmap')roadmap();else if(parts[0]==='about')editorialPage();else if(parts[0]==='track'&&['cloud','ai','agent'].includes(parts[1]))trackPage(parts[1]);else if(parts[0]==='labs')labsPage();else if(parts[0]==='problems')problemsPage();else{$('#app').innerHTML=`<main id="main" class="not-found" tabindex="-1"><h1>没有找到这个章节</h1><p>你可以返回知识库，或搜索相关内容。</p><a class="btn" href="#/">返回知识库</a></main>`;document.title='章节未找到 · InfraGuide'}const navHref=parts[0]==='track'?'#/track/'+parts[1]:parts[0]==='article'?'#/track/'+trackForModule(articles.find(a=>a.id===parts[1])?.module):parts[0]==='module'?'#/track/'+trackForModule(parts[1]):'#/'+parts[0];normalizeInternalLinks();document.querySelector('.top-nav a[href="'+publicRoute(navHref)+'"]')?.classList.add('active');$('#main')?.focus({preventScroll:true})}
function initInteractive(){initReaderActions();initAttentionDemo();initSystemInteractive();if($('#topology-demo')){let mode=0;const render=()=>{const info=[['单卡训练','一张 GPU 承载训练：先关注显存容量、算子效率与数据输入。'],['单机多卡','多张 GPU 在同一节点协作：新增梯度同步、数据分片与机内互联问题。'],['多机多卡','跨节点通信成为关键路径之一：同时验证网络、拓扑、任务协调与整体恢复。']];const node=(n,c)=>`<div class="gpu-node"><small>NODE ${n}</small><div class="gpu-chips">${Array.from({length:c},(_,i)=>`<span>GPU ${i}</span>`).join('')}</div></div>`;$('#topology-demo').innerHTML=`<div class="interactive"><div class="segmented" aria-label="训练拓扑">${info.map((x,i)=>`<button data-topology="${i}" class="${i===mode?'active':''}" aria-pressed="${i===mode}">${x[0]}</button>`).join('')}</div><div class="topology-nodes">${node('A',mode?2:1)}${mode===2?'<div class="network-bridge">⇄<br>节点间网络</div>'+node('B',2):''}</div><p class="demo-caption" aria-live="polite">${info[mode][1]}</p></div>`;$('#topology-demo').querySelectorAll('button').forEach(b=>b.onclick=()=>{mode=Number(b.dataset.topology);render()})};render()}
if($('#scaling-demo')){$('#scaling-demo').innerHTML=`<div class="interactive"><p class="demo-caption">计算示例：初始数值仅演示公式，不是实测基准。可填入同口径的真实结果。</p><div class="calc-fields"><label>单卡吞吐（样本/秒）<input id="base-throughput" type="number" min="0.01" step="any" value="100"></label><label>多卡吞吐（样本/秒）<input id="multi-throughput" type="number" min="0.01" step="any" value="620"></label><label>GPU 数量<input id="gpu-count" type="number" min="1" max="100000" step="1" value="8"></label></div><div id="calc-result" aria-live="polite"></div></div>`;const calc=()=>{const a=Number($('#base-throughput').value),b=Number($('#multi-throughput').value),n=Number($('#gpu-count').value);$('#calc-result').innerHTML=(!Number.isFinite(a)||!Number.isFinite(b)||a<=0||b<=0||!Number.isInteger(n)||n<1||n>100000)?'<p class="calc-error">请输入正数吞吐和有效的整数 GPU 数量。</p>':`<div class="calc-output"><div><strong>${(b/a).toFixed(2)}×</strong><small>吞吐加速比</small></div><div><strong>${(b/a/n*100).toFixed(1)}%</strong><small>扩展效率</small></div></div>${b/a/n>1?'<p class="demo-caption">效率超过 100%，请检查比较口径；缓存和工作负载变化也可能带来超线性结果。</p>':''}`};document.querySelectorAll('.calc-fields input').forEach(i=>i.addEventListener('input',calc));calc()}}
function search(q=''){const query=q.trim().toLowerCase();searchItems=ordered.filter(a=>!query||[a.title,a.desc,...a.tags,a.intro,...a.sections.flat()].join(' ').toLowerCase().includes(query));searchIndex=-1;$('#search-results').innerHTML=searchItems.length?searchItems.map(a=>`<a class="search-result" href="${articleURL(a.id)}"><small>${moduleFor(a.module).name} · ${a.number}</small><strong>${a.title}</strong><p>${a.desc}</p></a>`).join(''):`<p class="search-empty">没有找到相关内容。试试「GPU」「幂等」或「恢复」。</p>`}
function openSearch(){$('#search-dialog').showModal();$('#search-input').value='';search();$('#search-input').focus()}
$('#search-open').onclick=openSearch;$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-input').addEventListener('input',e=>search(e.target.value));$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close();if(e.target.closest('.search-result'))$('#search-dialog').close()});
$('#search-input').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!searchItems.length)return;searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+searchItems.length)%searchItems.length;document.querySelectorAll('.search-result').forEach((a,i)=>{a.classList.toggle('selected',i===searchIndex);if(i===searchIndex)a.scrollIntoView({block:'nearest'})})}else if(e.key==='Enter'&&searchItems.length){e.preventDefault();location.assign(articleURL(searchItems[Math.max(0,searchIndex)].id));$('#search-dialog').close()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#search-dialog').open)$('#search-dialog').close();else openSearch()}});
function applyTheme(dark){document.documentElement.classList.toggle('dark',dark);$('#theme').setAttribute('aria-label',dark?'切换浅色模式':'切换深色模式')}
applyTheme(readStore('cloudinfra-dark',false)===true);$('#theme').onclick=()=>{const dark=!document.documentElement.classList.contains('dark');applyTheme(dark);writeStore('cloudinfra-dark',dark)};
$('#mobile-menu').onclick=()=>{const open=$('.top-nav').classList.toggle('mobile-open');$('#mobile-menu').setAttribute('aria-expanded',open)};
document.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;renderModuleGrid()}const r=e.target.closest('[data-read]');if(r){progress[r.dataset.read]=!progress[r.dataset.read];const saved=writeStore('cloudinfra-progress',progress);r.classList.toggle('done',progress[r.dataset.read]);r.textContent=progress[r.dataset.read]?'✓ 已读 · 点击取消':'标记为已读';const a=articles.find(a=>a.id===r.dataset.read);$('.sidebar').outerHTML=sidebar(a.module,a.id);normalizeInternalLinks();toast(saved?(progress[a.id]?'已保存阅读进度':'已取消已读标记'):'本次进度已更新，浏览器存储不可用')}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){checks[e.target.dataset.check]=e.target.checked;if(!writeStore('cloudinfra-checks',checks))toast('浏览器存储不可用，勾选仅在本次会话保留')}});
$('.skip').onclick=e=>{e.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView()};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy-code]');if(!b)return;const code=b.closest('.code-block').querySelector('code').textContent;try{await navigator.clipboard.writeText(code);b.textContent='已复制';toast('代码已复制');setTimeout(()=>b.textContent='复制代码',1800)}catch{toast('无法访问剪贴板，请选中代码复制')}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/'))location.replace(publicRoute(location.hash))});if(location.hash.startsWith('#/'))location.replace(publicRoute(location.hash));else route();
